draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw Adam Smith
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.lineWidth = 3;
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // Draw Invisible Hand
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 + 20*Math.cos(t), H/2 + 70 + 20*Math.sin(t));
  ctx.lineTo(W/2 + 50 + 50*Math.cos(t), H/2 + 100 + 50*Math.sin(t));
  ctx.lineWidth = 5;
  ctx.stroke();

  // Draw Market
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.rect(W/2 + 100, H/2 - 50, 100, 100);
  ctx.lineWidth = 3;
  ctx.stroke();

  // Draw Wealth of Nations book
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.rect(W/2 - 150, H/2 - 50, 50, 100);
  ctx.lineWidth = 3;
  ctx.stroke();
  ctx.font = '20px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Wealth of', W/2 - 100, H/2 - 20);
  ctx.fillText('Nations', W/2 - 100, H/2 + 20);

  ctx.restore();
}
